<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Value\Validation\RespectValidator;

/**
 * Unit tests for {@see RespectValidator}.
 */
final class RespectValidatorUnitTest extends TestCase
{
    /**
     * Ensures lengthBetween proxies to a validator checking string length in range.
     */
    public function testLengthBetweenAcceptsInRange(): void
    {
        $validator = RespectValidator::lengthBetween(2, 5);

        $this->assertTrue($validator->isValid('abc'));
        $this->assertFalse($validator->isValid('a'));
        $this->assertFalse($validator->isValid('abcdef'));
    }

    /**
     * Ensures lengthGreaterThanOrEqual proxies to a min-length validator.
     */
    public function testLengthGreaterThanOrEqualAcceptsLongEnough(): void
    {
        $validator = RespectValidator::lengthGreaterThanOrEqual(3);

        $this->assertTrue($validator->isValid('abc'));
        $this->assertTrue($validator->isValid('abcdef'));
        $this->assertFalse($validator->isValid('ab'));
    }

    /**
     * Ensures lengthLessThanOrEqual proxies to a max-length validator.
     */
    public function testLengthLessThanOrEqualAcceptsShortEnough(): void
    {
        $validator = RespectValidator::lengthLessThanOrEqual(4);

        $this->assertTrue($validator->isValid('abc'));
        $this->assertTrue($validator->isValid(''));
        $this->assertFalse($validator->isValid('abcde'));
    }

    /**
     * Ensures greaterThanOrEqual proxies to a min-value validator.
     */
    public function testGreaterThanOrEqualAcceptsAboveMin(): void
    {
        $validator = RespectValidator::greaterThanOrEqual(5);

        $this->assertTrue($validator->isValid(5));
        $this->assertTrue($validator->isValid(10));
        $this->assertFalse($validator->isValid(4));
    }

    /**
     * Ensures lessThanOrEqual proxies to a max-value validator.
     */
    public function testLessThanOrEqualAcceptsBelowMax(): void
    {
        $validator = RespectValidator::lessThanOrEqual(10);

        $this->assertTrue($validator->isValid(10));
        $this->assertTrue($validator->isValid(1));
        $this->assertFalse($validator->isValid(11));
    }

    /**
     * Ensures unknown method names are forwarded to the underlying validator class.
     */
    public function testDefaultFallthroughForwardsToValidator(): void
    {
        $validator = RespectValidator::alwaysValid();

        $this->assertTrue($validator->isValid('anything'));
        $this->assertTrue($validator->isValid(null));
    }
}
